from dataclasses import dataclass


@dataclass
class Order:
    item: str
    quantity: int

    def validate(self):
        if self.quantity <= 0:
            raise ValueError("quantity must be positive")

tests:
assert Order("apple", 3).quantity == 3

try:
    Order("apple", -1)
except ValueError:
    pass
else:
    raise AssertionError("an order with a negative quantity was constructed")

